-- Integrity of the M0E golden data (tests/golden/oracle/m0e, generated by
-- tools/oracle/export_m0e_cases.py): every file loads on each Lua backend, and the
-- recorded original observations are internally consistent (conservation, counts,
-- field labels). These checks guard the exported data, not an implementation.
local S = {}

local DIR = "tests/golden/oracle/m0e/"

local function load_file(T, name)
	local text = T.read(DIR .. name)
	local chunk = assert((loadstring or load)(text, "=" .. name))
	return chunk()
end

local function index(T)
	return load_file(T, "index.lua")
end

local function each(T, prefix)
	local out = {}
	for _, name in ipairs(index(T).files) do
		if name:sub(1, #prefix) == prefix then out[#out + 1] = { name = name, data = load_file(T, name) } end
	end
	return out
end

function S.all_files_load(T)
	local files = index(T).files
	T.ok(#files >= 10, "index lists the golden files")
	for _, name in ipairs(files) do
		T.eq(type(load_file(T, name)), "table", name)
	end
end

-- E1: initial - current resource amounts = cumulative deposits + carried cargo, after every
-- callback; every genuine worker delivers at least twice.
function S.e1_conservation(T)
	local scenes = each(T, "e1_")
	T.eq(#scenes, 4)
	for _, f in ipairs(scenes) do
		local g = f.data
		local amounts, total = {}, 0
		for i, a in ipairs(g.baseline_amounts) do amounts[i] = a; total = total + a end
		local base = total
		local ai, si, cumulative = 1, 1, 0
		local run_pos = {}
		for w = 1, #g.workers do
			run_pos[w] = 1
			T.eq(#g.positions[w], 2 * g.callbacks, f.name .. " positions")
		end
		for cb = 1, g.callbacks do
			while g.amounts[ai] and g.amounts[ai][1] == cb do
				local c = g.amounts[ai]
				total = total - amounts[c[2]] + c[3]
				amounts[c[2]] = c[3]
				ai = ai + 1
			end
			while g.stock[si] and g.stock[si][1] == cb do
				cumulative = g.stock[si][3]
				si = si + 1
			end
			local carried = 0
			for w = 1, #g.workers do
				local runs = g.runs[w]
				while runs[run_pos[w] + 1] and runs[run_pos[w] + 1][1] <= cb do run_pos[w] = run_pos[w] + 1 end
				carried = carried + runs[run_pos[w]][5]
			end
			T.eq(base - total, cumulative + carried, f.name .. " conservation at callback " .. cb)
		end
		T.eq(ai, #g.amounts + 1, f.name .. " amount changes consumed")
		local per = {}
		for _, d in ipairs(g.deposits) do per[d[2]] = (per[d[2]] or 0) + 1 end
		for _, w in ipairs(g.workers) do T.ok((per[w] or 0) >= 2, f.name .. " worker " .. w .. " deposits twice") end
	end
end

local function count(list, ty)
	for _, p in ipairs(list) do if p[1] == ty then return p[2] end end
	return nil
end

-- E2: the final state agrees with the recorded actual tuple and completion callbacks.
function S.e2_final_state(T)
	local profiles = 0
	for _, f in ipairs(each(T, "e2_")) do
		local g = f.data
		if g.profile then
			profiles = profiles + 1
			local fin = g.final
			T.eq(fin.stocks[1], g.actual[2][1], f.name .. " minerals")
			T.eq(fin.stocks[2], g.actual[2][2], f.name .. " gas")
			T.eq(fin.town[1], g.actual[3], f.name .. " Town workers")
			for ty, n in pairs(g.actual[1]) do T.eq(count(fin.completed, tonumber(ty)), n, f.name .. " completed " .. ty) end
			local last = 0
			for _, e in ipairs(g.timeline) do
				T.ok(e.c > last, f.name .. " timeline order")
				last = e.c
			end
			for _, c in ipairs(g.completion_callbacks) do T.ok(c[2] <= g.callbacks, f.name .. " completion in window") end
		end
	end
	T.eq(profiles, 3)
end

-- E3: every recorded tuple carries one label per value.
function S.e3_labels(T)
	local n = 0
	for _, f in ipairs(each(T, "e3_")) do
		if f.data.family then
			for _, c in ipairs(f.data.cases) do
				T.eq(#c.fields, #c.actual, f.name .. " " .. c.case)
				n = n + 1
			end
		end
	end
	T.eq(n, 62)
end

-- E3 emulator: completion stamping returned, and each later delivery adds 8 gas taken from the geyser.
function S.e3_extractor_completion(T)
	local g = load_file(T, "e3_extractor_completion_emulator.lua")
	T.eq(g.completed_state[1], 149)
	T.eq(g.completed_state[4], 750 * 256)
	T.eq(#g.creep_stamp_return_frames, 1)
	T.eq(g.creep_stamp_return_frames[1], g.creep_stamp_call_frames[1])
	T.ok(#g.deliveries >= 1, "gas delivered")
	local gas = 0
	for _, d in ipairs(g.deliveries) do
		T.eq(d[2], gas + 8)
		T.eq(d[3], g.geyser_before[6] - d[2])
		gas = d[2]
	end
end

-- E0 emulator: the checkpoint RNG states are the per-frame states at those frames.
function S.e0_clock(T)
	local g = load_file(T, "e0_clock_emulator.lua")
	T.eq(g.elapsed_period_frames, 16)
	for _, c in ipairs(g.checkpoints) do T.eq(g.rng_by_frame[c[1]], c[2], "rng at frame " .. c[1]) end
end

return S
